  "narrating": {img:"🗣️", ex5:[{t:1,en:"The author is narrating her own audiobook.",kr:"그 작가는 자신의 오디오북을 직접 내레이션하고 있다."},{t:2,en:"He is good at narrating stories to children.",kr:"그는 아이들에게 이야기를 들려주는 것을 잘한다."},{t:3,en:"The documentary featured a famous actor narrating the history.",kr:"그 다큐멘터리는 유명 배우가 역사를 내레이션하는 것을 특징으로 했다."},{t:4,en:"She spent hours narrating her travel experiences in her diary.",kr:"그녀는 자신의 일기장에 여행 경험을 서술하는 데 몇 시간을 보냈다."},{t:5,en:"The news reporter was narrating the live events from the scene.",kr:"그 뉴스 기자는 현장에서 실시간 사건들을 보도하고 있었다."}]},
  "narration": {img:"🎙️", ex5:[{t:1,en:"The film features a calm and steady narration.",kr:"그 영화는 차분하고 안정적인 내레이션이 특징이다."},{t:2,en:"Her narration made the story much easier to follow.",kr:"그녀의 서술 덕분에 이야기를 따라가기가 훨씬 쉬웠다."},{t:3,en:"The documentary includes a moving narration by a famous actor.",kr:"그 다큐멘터리에는 유명 배우의 감동적인 내레이션이 포함되어 있다."},{t:4,en:"He provided a clear narration of the historical events.",kr:"그는 역사적 사건들에 대해 명확하게 서술했다."},{t:5,en:"The narration helps the audience understand the character's thoughts.",kr:"내레이션은 관객이 등장인물의 생각을 이해하도록 돕는다."}]},
  "narrative": {img:"📖", ex5:[{t:1,en:"The narrative is clear.",kr:"그 서사는 명확하다."},{t:2,en:"The narrative shifted.",kr:"그 이야기가 바뀌었다."},{t:3,en:"We shaped the narrative.",kr:"우리는 서사를 빚었다."},{t:4,en:"The film gave us a narrative.",kr:"그 영화는 우리에게 서사를 안겼다."},{t:5,en:"We found the narrative gripping.",kr:"우리는 그 서사가 흥미진진하다고 느꼈다."}]},
  "narratives": {img:"📚", ex5:[{t:1,en:"The book includes several short narratives.",kr:"그 책은 몇 개의 짧은 이야기들을 포함하고 있다."},{t:2,en:"He writes interesting narratives about his travels.",kr:"그는 자신의 여행에 관한 흥미로운 서술을 쓴다."},{t:3,en:"These narratives help us understand history.",kr:"이 이야기들은 우리가 역사를 이해하는 데 도움을 준다."},{t:4,en:"The students created their own creative narratives.",kr:"학생들은 자신만의 창의적인 이야기를 만들었다."},{t:5,en:"The movie uses multiple narratives to tell the story.",kr:"그 영화는 이야기를 전달하기 위해 여러 서술 방식을 사용한다."}]},
  "narrator": {img:"📖", ex5:[{t:1,en:"The narrator of the story has a very calm and pleasant voice.",kr:"그 이야기의 서술자는 매우 차분하고 듣기 좋은 목소리를 가지고 있습니다."},{t:2,en:"The narrator explains what the characters are thinking.",kr:"서술자는 등장인물들이 무슨 생각을 하는지 설명해 줍니다."},{t:3,en:"I was chosen to be the narrator for the school play.",kr:"나는 학교 연극의 내레이터로 뽑혔습니다."},{t:4,en:"The narrator's perspective makes the story more interesting.",kr:"서술자의 관점은 이야기를 더 흥미롭게 만듭니다."},{t:5,en:"Listen carefully to what the narrator says at the beginning.",kr:"시작 부분에서 서술자가 하는 말을 주의 깊게 들으세요."}]},
  "narrow": {img:"↔️", ex5:[{t:1,en:"The path is narrow.",kr:"그 길은 좁다."},{t:2,en:"The gap is narrowing.",kr:"그 격차가 좁혀지고 있다."},{t:3,en:"We narrow the list.",kr:"우리는 목록을 좁힌다."},{t:4,en:"The road gave us a narrow lane.",kr:"그 도로는 우리에게 좁은 차선을 주었다."},{t:5,en:"We found the hall narrow.",kr:"우리는 그 복도가 좁다고 느꼈다."}]},
  "narrowed": {img:"🛣️", ex5:[{t:1,en:"The road narrowed as we drove into the village.",kr:"마을로 들어갈수록 도로가 좁아졌어요."},{t:2,en:"He narrowed his eyes to see the sign better.",kr:"그는 표지판을 더 잘 보려고 눈을 가늘게 떴어요."},{t:3,en:"The gap between the two teams has narrowed.",kr:"두 팀 사이의 격차가 줄어들었어요."},{t:4,en:"The list of candidates has been narrowed down to three.",kr:"후보자 명단이 세 명으로 좁혀졌어요."},{t:5,en:"The river narrowed significantly at this point.",kr:"강폭이 이 지점에서 상당히 좁아졌어요."}]},
